/**
 * Ruprizzle Studio Embedded Alpine.js Micro-Interactivity Runtime
 * Handles inline double-click cell edits, modal dialogs, and keybindings.
 */
(function() {
  function initTree(root) {
    const scopes = (root || document).querySelectorAll('[x-data]');
    scopes.forEach(scope => {
      if (scope._alpineInit) return;
      scope._alpineInit = true;

      const expr = scope.getAttribute('x-data') || '{}';
      let state = {};
      try {
        state = (new Function(`return ${expr}`))();
      } catch(e) {
        state = {};
      }

      function update() {
        const showElements = scope.querySelectorAll('[x-show]');
        showElements.forEach(el => {
          const cond = el.getAttribute('x-show');
          try {
            const visible = (new Function(...Object.keys(state), `return ${cond}`))(...Object.values(state));
            el.style.display = visible ? '' : 'none';
          } catch(e) {}
        });
      }

      // Bind events
      const clickElements = scope.querySelectorAll('[@click], [x-on\\:click]');
      clickElements.forEach(el => {
        const handler = el.getAttribute('@click') || el.getAttribute('x-on:click');
        el.addEventListener('click', (e) => {
          try {
            (new Function('$event', ...Object.keys(state), handler))(e, ...Object.values(state));
            update();
          } catch(err) {}
        });
      });

      const dblClickElements = scope.querySelectorAll('[@dblclick], [x-on\\:dblclick]');
      dblClickElements.forEach(el => {
        const handler = el.getAttribute('@dblclick') || el.getAttribute('x-on:dblclick');
        el.addEventListener('dblclick', (e) => {
          try {
            (new Function('$event', ...Object.keys(state), handler))(e, ...Object.values(state));
            update();
          } catch(err) {}
        });
      });

      update();
    });
  }

  document.addEventListener('DOMContentLoaded', () => initTree(document));
  window.Alpine = { initTree: initTree, start: () => initTree(document) };
})();
